new = '''// Writes all bytes of `data` to `f`, flushing and closing it.
bool write_stream(std::FILE* f, const std::string& data) {
    bool ok = true;
    if (!data.empty() &&
        std::fwrite(data.data(), 1, data.size(), f) != data.size())
        ok = false;
    if (ok && std::fflush(f) != 0) ok = false;
    if (std::fclose(f) != 0) ok = false;
    return ok;
}

// Writes `data` to `path` without disturbing it unless everything succeeds:
// the image is staged in a sibling temporary file and renamed into place, so a
// failed build leaves an existing destination untouched.  If no temporary name
// is available the data is written directly.
void write_image(const std::string& path, const std::string& data) {
    const std::string tmp = path + ".planb64-tmp";
    std::FILE* f = std::fopen(tmp.c_str(), "wb");
    if (f == nullptr) {  // fall back to a direct write
        std::FILE* direct = std::fopen(path.c_str(), "wb");
        if (direct == nullptr) fail("cannot create output file: " + path);
        if (!write_stream(direct, data)) fail("cannot write output file: " + path);
        return;
    }
    if (!write_stream(f, data)) {
        std::remove(tmp.c_str());
        fail("cannot write output file: " + path);
    }
    if (std::rename(tmp.c_str(), path.c_str()) != 0) {
        std::remove(tmp.c_str());
        fail("cannot install output file: " + path);
    }
}'''
